using ScriptArt.Compiler.Diagnostics;
using ScriptArt.Compiler.Emit;
using ScriptArt.GraphModel;

namespace ScriptArt.ProjectSystem;

public enum GeneratedFileChangeKind
{
    Added,
    Modified,
    Deleted,
}

/// <summary>
/// A generated file that writing would add, change, or delete. <paramref name="OldText"/> is empty for an added file and
/// <paramref name="NewText"/> for a deleted one.
/// </summary>
public sealed record GeneratedFileChange(string Path, GeneratedFileChangeKind Kind, string OldText, string NewText)
{
    /// <summary>The change as a unified diff, with <paramref name="displayPath"/> in its headers.</summary>
    public string UnifiedDiff(string displayPath) => TextDiff.Unified(
        Kind == GeneratedFileChangeKind.Added ? "/dev/null" : "a/" + displayPath,
        Kind == GeneratedFileChangeKind.Deleted ? "/dev/null" : "b/" + displayPath,
        OldText,
        NewText);
}

/// <summary>
/// Writes generated sources into the project's generated-code folder while enforcing the ownership model:
/// only files that carry the generator's header are ever overwritten or deleted. See docs/CODE_GENERATION.md.
/// </summary>
public static class GeneratedFileWriter
{
    public const string OwnershipConflictId = "VSP0001";

    /// <summary>
    /// Works out what <see cref="Write"/> would do without touching the disk: the files it would add, change, or delete, or the
    /// ownership conflicts that would stop it.
    /// </summary>
    /// <returns>Diagnostics for ownership conflicts; empty when writing can go ahead.</returns>
    public static IReadOnlyList<GraphDiagnostic> Plan(string directory, IReadOnlyList<GeneratedSource> sources, out IReadOnlyList<GeneratedFileChange> changes)
    {
        ArgumentNullException.ThrowIfNull(sources);
        List<GraphDiagnostic> conflicts = [];
        List<GeneratedFileChange> planned = [];
        changes = planned;
        var expected = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (GeneratedSource source in sources)
        {
            string path = Path.GetFullPath(Path.Combine(directory, source.RelativePath));
            expected.Add(path);
            if (!File.Exists(path))
            {
                planned.Add(new GeneratedFileChange(path, GeneratedFileChangeKind.Added, "", source.Text));
                continue;
            }

            string existing = File.ReadAllText(path);
            if (!GeneratedSource.IsGeneratedText(existing))
            {
                conflicts.Add(new GraphDiagnostic(OwnershipConflictId, DiagnosticSeverity.Error,
                    $"'{path}' exists but was not generated by ScriptArt Code. Rename or move it; it will not be overwritten.",
                    FilePath: path));
            }
            else if (existing != source.Text)
            {
                planned.Add(new GeneratedFileChange(path, GeneratedFileChangeKind.Modified, existing, source.Text));
            }
        }

        if (conflicts.Count > 0)
        {
            planned.Clear();
            return conflicts;
        }

        // Generated files whose graph no longer exists are deleted. Handwritten files in the folder are left alone.
        if (Directory.Exists(directory))
        {
            foreach (string path in Directory.EnumerateFiles(directory, "*.cs").Order(StringComparer.Ordinal))
            {
                string fullPath = Path.GetFullPath(path);
                if (!expected.Contains(fullPath) && File.ReadAllText(fullPath) is var text && GeneratedSource.IsGeneratedText(text))
                {
                    planned.Add(new GeneratedFileChange(fullPath, GeneratedFileChangeKind.Deleted, text, ""));
                }
            }
        }

        return [];
    }

    /// <summary>
    /// Writes <paramref name="sources"/> to <paramref name="directory"/>. Nothing is written when any target is a handwritten file.
    /// Unchanged files are not rewritten, so builds stay incremental.
    /// </summary>
    /// <returns>Diagnostics for ownership conflicts; empty on success.</returns>
    public static IReadOnlyList<GraphDiagnostic> Write(string directory, IReadOnlyList<GeneratedSource> sources, out IReadOnlyList<string> changedFiles)
    {
        IReadOnlyList<GraphDiagnostic> conflicts = Plan(directory, sources, out IReadOnlyList<GeneratedFileChange> changes);
        List<string> changed = [];
        changedFiles = changed;
        if (conflicts.Count > 0)
        {
            return conflicts;
        }

        Directory.CreateDirectory(directory);
        foreach (GeneratedFileChange change in changes)
        {
            if (change.Kind == GeneratedFileChangeKind.Deleted)
            {
                File.Delete(change.Path);
            }
            else
            {
                AtomicFile.WriteAllText(change.Path, change.NewText);
            }

            changed.Add(change.Path);
        }

        return [];
    }
}
